    /// The LLM config, or defaults when none is saved. The API key never comes
    /// back; `anthropic_api_key_set` says whether one is stored.
    pub async fn llm_config(&self) -> Result<LlmConfigDto, MnemisError> {
        let path = self.config_path();
        run(async move {
            let key_set = mnemis_engine::llm::anthropic_api_key().await.is_some();
            let config_path = path.display().to_string();
            Ok(match config::load(Some(&path)) {
                Ok(cfg) => LlmConfigDto {
                    thinking_level: cfg.llm.resolved_thinking_level(),
                    provider: cfg.llm.provider,
                    base_url: cfg.llm.base_url,
                    chat_model: cfg.llm.chat_model,
                    bearer_token: cfg.llm.bearer_token,
                    anthropic_api_key: None,
                    anthropic_api_key_set: key_set,
                    config_path,
                },
                Err(_) => LlmConfigDto {
                    anthropic_api_key_set: key_set,
                    config_path,
                    ..Default::default()
                },
            })
        })
        .await
    }

    /// Save the LLM config (and a new API key, when given) and rebuild the
    /// live LLM so the next sync uses it.
    pub async fn save_llm_config(self: Arc<Self>, cfg: LlmConfigDto) -> Result<(), MnemisError> {
        let engine = Arc::clone(&self);
        run(async move {
            if let Some(key) = cfg.anthropic_api_key.as_deref().map(str::trim)
                && !key.is_empty()
            {
                mnemis_engine::secrets::store(mnemis_engine::anthropic::API_KEY_REF, key).await?;
            }
            let path = engine.config_path();
            config::save_llm_at(
                &path,
                &config::LlmSection {
                    provider: cfg.provider,
                    base_url: cfg.base_url,
                    chat_model: cfg.chat_model,
                    bearer_token: cfg.bearer_token.filter(|s| !s.trim().is_empty()),
                    max_context_tokens: None,
                    request_timeout_secs: None,
                    chat_idle_timeout_secs: None,
                    thinking_level: Some(cfg.thinking_level),
                },
            )?;
            match LlmStack::build(&config::load(Some(&path))?, engine.apple.as_ref()).await {
                Ok(stack) => {
                    engine.set_llm(Some(Arc::new(stack)));
                    Ok(())
                }
                Err(e) => {
                    engine.set_llm(None);
                    Err(e.context("saved, but the LLM isn't usable yet"))
                }
            }
        })
        .await
    }

